import { useState, useEffect, useRef, useCallback } from 'react';
import { toast } from 'sonner';

// 语言代码映射表
const LANG_MAP: Record<string, { native: string; gtts: string; label: string }> = {
  'en': { native: 'en-US', gtts: 'en', label: '英语' },
  'ko': { native: 'ko-KR', gtts: 'ko', label: '韩语' },
  'ja': { native: 'ja-JP', gtts: 'ja', label: '日语' },
  'th': { native: 'th-TH', gtts: 'th', label: '泰语' },
  'zh': { native: 'zh-CN', gtts: 'zh-CN', label: '中文' },
  'en-US': { native: 'en-US', gtts: 'en', label: '英语' },
  'ko-KR': { native: 'ko-KR', gtts: 'ko', label: '韩语' },
  'ja-JP': { native: 'ja-JP', gtts: 'ja', label: '日语' },
  'th-TH': { native: 'th-TH', gtts: 'th', label: '泰语' },
  'zh-CN': { native: 'zh-CN', gtts: 'zh-CN', label: '中文' },
};

interface UseTTSReturn {
  isSpeaking: boolean;
  speakingText: string;
  speak: (text: string, lang?: string) => void;
  stop: () => void;
}

/**
 * 双层 TTS hook
 * 第一层：原生 SpeechSynthesis（支持的语言走原生）
 * 第二层：Google Translate TTS（原生不支持的语言走降级）
 *
 * 移动端兼容：
 * - 首次点击时在用户手势内直接触发播放
 * - audio.play() 放在 click 同步调用栈中，确保 iOS Safari 允许
 */
export function useTTS(): UseTTSReturn {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [speakingText, setSpeakingText] = useState('');
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const synthReadyRef = useRef(false);

  // 页面加载时预初始化 speechSynthesis
  useEffect(() => {
    if (typeof window === 'undefined') return;
    if (!('speechSynthesis' in window)) return;

    // 触发 getVoices 加载语音列表
    try {
      window.speechSynthesis.getVoices();
    } catch { /* noop */ }

    // voiceschanged 事件标记 ready
    const handleVoicesChanged = () => {
      synthReadyRef.current = true;
    };
    window.speechSynthesis.addEventListener?.('voiceschanged', handleVoicesChanged);

    // 500ms 兜底标记 ready
    const timer = setTimeout(() => { synthReadyRef.current = true; }, 500);

    return () => {
      window.speechSynthesis.removeEventListener?.('voiceschanged', handleVoicesChanged);
      clearTimeout(timer);
      // 卸载时停止
      try { window.speechSynthesis.cancel(); } catch { /* noop */ }
      if (audioRef.current) {
        try { audioRef.current.pause(); } catch { /* noop */ }
        audioRef.current = null;
      }
    };
  }, []);

  const stop = useCallback(() => {
    // 停止原生
    try { window.speechSynthesis.cancel(); } catch { /* noop */ }
    // 停止降级音频
    if (audioRef.current) {
      try {
        audioRef.current.pause();
        audioRef.current.currentTime = 0;
      } catch { /* noop */ }
    }
    setIsSpeaking(false);
    setSpeakingText('');
  }, []);

  // 检查原生是否支持目标语言
  const isLangSupportedBySynth = useCallback((targetLang: string): boolean => {
    if (!('speechSynthesis' in window)) return false;
    try {
      const voices = window.speechSynthesis.getVoices();
      if (!voices || voices.length === 0) return false;
      // 粤语要精确匹配 zh-HK（不能随便用 zh-CN 凑），其他语言宽松匹配语言前缀
      if (targetLang.toLowerCase() === 'zh-hk') {
        return voices.some(v => v.lang.toLowerCase() === 'zh-hk' || v.lang.toLowerCase() === 'zh-hk-hk');
      }
      const langPrefix = targetLang.toLowerCase().split('-')[0];
      return voices.some(v => v.lang.toLowerCase().startsWith(langPrefix));
    } catch {
      return false;
    }
  }, []);

  const speak = useCallback((text: string, lang: string = 'en') => {
    if (!text || !text.trim()) return;

    // 先停止所有正在播放的
    stop();

    const langCfg = LANG_MAP[lang] || LANG_MAP['en'];
    const displayText = text.length > 20 ? text.slice(0, 20) + '...' : text;
    setSpeakingText(displayText);

    // 第一层：原生 SpeechSynthesis
    if ('speechSynthesis' in window && isLangSupportedBySynth(langCfg.native)) {
      try {
        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = langCfg.native;
        utterance.rate = 0.9;
        utterance.pitch = 1;

        // 匹配最优 voice：粤语精确匹配 zh-HK（HiuMaan/WanLung/Sinji 等香港粤语语音），其他语言前缀匹配
        try {
          const voices = window.speechSynthesis.getVoices();
          const nativeLang = langCfg.native.toLowerCase();
          let matched: SpeechSynthesisVoice | undefined;

          if (nativeLang === 'zh-hk') {
            // 粤语：优先找最地道的香港粤语女声/男声
            const preferredNames = ['HiuMaan', 'WanLung', 'Sinji', 'Tracy', 'George', 'Alex']; // 常见粤语语音名
            for (const name of preferredNames) {
              matched = voices.find(v =>
                (v.lang.toLowerCase() === 'zh-hk' || v.lang.toLowerCase() === 'zh-hk-hk') &&
                v.name.toLowerCase().includes(name.toLowerCase())
              );
              if (matched) break;
            }
            // 没找到优选名称就找任何 zh-HK 语音
            if (!matched) {
              matched = voices.find(v =>
                v.lang.toLowerCase() === 'zh-hk' || v.lang.toLowerCase() === 'zh-hk-hk'
              );
            }
          } else {
            matched = voices.find(v =>
              v.lang.toLowerCase().startsWith(nativeLang.split('-')[0])
            );
          }

          if (matched && matched.name) {
            utterance.voice = matched;
          }
        } catch { /* noop */ }

        utterance.onstart = () => {
          setIsSpeaking(true);
        };
        utterance.onend = () => {
          setIsSpeaking(false);
          setSpeakingText('');
        };
        utterance.onerror = (e) => {
          setIsSpeaking(false);
          setSpeakingText('');
          if (e.error && e.error !== 'interrupted' && e.error !== 'canceled') {
            // 原生失败，降级到 Google TTS
            playWithGoogleTTS(text, langCfg.gtts, displayText);
          }
        };

        window.speechSynthesis.speak(utterance);
        setIsSpeaking(true);
        synthReadyRef.current = true;
        return;
      } catch {
        // 原生异常，降级
      }
    }

    // 第二层：Google Translate TTS 降级
    playWithGoogleTTS(text, langCfg.gtts, displayText);
  }, [stop, isLangSupportedBySynth]);

  // 播放 Google Translate TTS 降级音频
  const playWithGoogleTTS = useCallback((text: string, langCode: string, displayText: string) => {
    try {
      const url = `https://translate.google.com/translate_tts?ie=UTF-8&q=${encodeURIComponent(text)}&tl=${langCode}&client=tw-ob`;

      // 复用同一个 audio 元素
      if (!audioRef.current) {
        audioRef.current = new Audio();
      }
      const audio = audioRef.current;
      audio.src = url;
      audio.crossOrigin = 'anonymous';

      audio.onplay = () => {
        setIsSpeaking(true);
        setSpeakingText(displayText);
      };
      audio.onended = () => {
        setIsSpeaking(false);
        setSpeakingText('');
      };
      audio.onerror = () => {
        setIsSpeaking(false);
        setSpeakingText('');
        toast.error('当前设备暂不支持该语言朗读');
      };

      const playPromise = audio.play();
      if (playPromise && typeof playPromise.catch === 'function') {
        playPromise.catch(() => {
          setIsSpeaking(false);
          setSpeakingText('');
          toast.error('当前设备暂不支持该语言朗读');
        });
      }
    } catch {
      setIsSpeaking(false);
      setSpeakingText('');
      toast.error('当前设备暂不支持该语言朗读');
    }
  }, []);

  return { isSpeaking, speakingText, speak, stop };
}
